// Preconditions: list is a valid, non-null pointer owned by the harness.
// Call target API to initialize the list head or standalone item.
list_init(list);

// Track state: after init, the node is self-referential and empty.
FUZZ_SET_ATTR_INT(list, "initialized", 1);
// Mark as a potential head; when used as a list head in other stubs, this will be relied upon.
FUZZ_SET_ATTR_INT(list, "is_head", 1);
// For a freshly initialized head, element count is zero.
FUZZ_SET_ATTR_INT(list, "count", 0);
// For a standalone item or head, its logical head pointer is itself.
FUZZ_SET_ATTR_PTR(list, "head", list);
// Not linked into any external list yet.
FUZZ_SET_ATTR_INT(list, "linked", 0);

// Validation: list has been initialized and marked empty with count=0; it is returned for reuse.

// Enforce: item and list must be distinct.
if (item == list) { FUZZ_BAIL(); }

// Ensure list is an initialized head. If not yet initialized, initialize it here to satisfy API precondition.
if (!FUZZ_GET_ATTR_INT(list, "initialized")) {
    list_init(list);
    FUZZ_SET_ATTR_INT(list, "initialized", 1);
    FUZZ_SET_ATTR_INT(list, "count", 0);
    FUZZ_SET_ATTR_PTR(list, "head", list);
}
FUZZ_SET_ATTR_INT(list, "is_head", 1);

// Ensure item is a standalone node (not linked). If not initialized, initialize to a self-list first.
if (!FUZZ_GET_ATTR_INT(item, "initialized")) {
    list_init(item);
    FUZZ_SET_ATTR_INT(item, "initialized", 1);
    FUZZ_SET_ATTR_PTR(item, "head", item);
    FUZZ_SET_ATTR_INT(item, "linked", 0);
}
if (FUZZ_GET_ATTR_INT(item, "linked")) { FUZZ_BAIL(); }

// Call target API to prepend.
list_item_prepend(item, list);

// Update attributes to reflect linkage into list.
FUZZ_SET_ATTR_INT(item, "linked", 1);
FUZZ_SET_ATTR_PTR(item, "head", list);
FUZZ_SET_ATTR_INT(list, "count", FUZZ_GET_ATTR_INT(list, "count") + 1);

// Validation: preconditions ensured (initialized head, unlinked item, distinct pointers). Both objects persist and are returned.

// Enforce: item and list must be distinct.
if (item == list) { FUZZ_BAIL(); }

// Ensure list is an initialized head. Initialize if needed to satisfy API precondition.
if (!FUZZ_GET_ATTR_INT(list, "initialized")) {
    list_init(list);
    FUZZ_SET_ATTR_INT(list, "initialized", 1);
    FUZZ_SET_ATTR_INT(list, "count", 0);
    FUZZ_SET_ATTR_PTR(list, "head", list);
}
FUZZ_SET_ATTR_INT(list, "is_head", 1);

// Ensure item is standalone (not currently linked). Initialize if needed.
if (!FUZZ_GET_ATTR_INT(item, "initialized")) {
    list_init(item);
    FUZZ_SET_ATTR_INT(item, "initialized", 1);
    FUZZ_SET_ATTR_PTR(item, "head", item);
    FUZZ_SET_ATTR_INT(item, "linked", 0);
}
if (FUZZ_GET_ATTR_INT(item, "linked")) { FUZZ_BAIL(); }

// Call target API to append.
list_item_append(item, list);

// Update attributes to reflect linkage into list.
FUZZ_SET_ATTR_INT(item, "linked", 1);
FUZZ_SET_ATTR_PTR(item, "head", list);
FUZZ_SET_ATTR_INT(list, "count", FUZZ_GET_ATTR_INT(list, "count") + 1);

// Validation: requirements enforced (initialized head, unlinked item, item != list); objects returned for continued fuzzing.

// Item must currently be linked into a well-formed list.
if (!FUZZ_GET_ATTR_INT(item, "linked")) { FUZZ_BAIL(); }
struct list_item *head = (struct list_item *)FUZZ_GET_ATTR_PTR(item, "head");
if (!head) { FUZZ_BAIL(); }

// Call target API to delete the item from its list; item becomes self-referential.
list_item_del(item);

// Update attributes on the removed item.
FUZZ_SET_ATTR_INT(item, "linked", 0);
FUZZ_SET_ATTR_INT(item, "initialized", 1);
FUZZ_SET_ATTR_PTR(item, "head", item);

// Decrement count on the head if it is tracked as a head.
if (FUZZ_GET_ATTR_INT(head, "is_head")) {
    int cnt = FUZZ_GET_ATTR_INT(head, "count");
    if (cnt > 0) { FUZZ_SET_ATTR_INT(head, "count", cnt - 1); }
}

// Validation: only deletes items known to be linked; post-state reinitialized and safe to reuse. Head count adjusted when known.

// Preconditions: list must be the initialized head and item must be linked into this same list.
if (!FUZZ_GET_ATTR_INT(list, "initialized")) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(list, "is_head", 1);
if (item == list) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(item, "linked")) { FUZZ_BAIL(); }
if ((struct list_item *)FUZZ_GET_ATTR_PTR(item, "head") != list) { FUZZ_BAIL(); }

// Call target API; result is an int (0 or nonzero). We don't assert value because we don't track exact order.
int is_last = list_item_is_last(item, list);
(void)is_last;

// Validation: Only called when membership is well-defined (same list, not the head). Both nodes are returned unchanged.

// Preconditions: old_list must be an initialized head. To ensure safe relink without
// additional structure knowledge, restrict to empty lists (safe case per API).
if (!FUZZ_GET_ATTR_INT(old_list, "initialized")) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(old_list, "is_head", 1);
int cnt = FUZZ_GET_ATTR_INT(old_list, "count");
if (cnt != 0) { FUZZ_BAIL(); }

// Prepare new_list. For empty lists, new_list can be freshly initialized.
if (!FUZZ_GET_ATTR_INT(new_list, "initialized")) {
    list_init(new_list);
    FUZZ_SET_ATTR_INT(new_list, "initialized", 1);
}

// Call target API to relink the head pointer.
list_relink(new_list, old_list);

// Transfer head role and counters to new head; old head is no longer the active head.
FUZZ_SET_ATTR_INT(new_list, "is_head", 1);
FUZZ_SET_ATTR_INT(new_list, "count", 0);
FUZZ_SET_ATTR_PTR(new_list, "head", new_list);
FUZZ_SET_ATTR_INT(old_list, "is_head", 0);

// Validation: Relink performed only for empty lists (guaranteed-safe path). Head role transferred and both nodes returned.

// Construct a fresh list node and initialize it as a standalone, valid list_item.
// No inputs are required; the stub allocates and returns a ready-to-use node.

// Allocate the node; keep allocation small and bounded.
struct list_item *node = (struct list_item *)malloc(sizeof(struct list_item));
if (!node) { FUZZ_BAIL(); }

// Always initialize the node to a self-referential empty list per API contract.
list_init(node);

// Track core invariants/state for downstream stubs.
FUZZ_SET_ATTR_INT(node, "initialized", 1);
FUZZ_SET_ATTR_INT(node, "linked", 0);           // not linked into any external list yet
FUZZ_SET_ATTR_PTR(node, "head", node);          // logical head is itself for a standalone node

// Randomly decide whether this node should be treated as a list head sentinel in future ops.
// Both head and non-head paths are valid and expand coverage of APIs that require heads.
unsigned int choose_head = *FUZZ_PARAM(unsigned int);
int is_head = (choose_head & 1) ? 1 : 0;
FUZZ_SET_ATTR_INT(node, "is_head", is_head);
if (is_head) {
    // For a head, maintain an element count attribute. Freshly initialized head has zero members.
    FUZZ_SET_ATTR_INT(node, "count", 0);
}

// Property-based validation: after list_init, next/prev must point to itself.
FUZZ_ASSERT(node->next == node && node->prev == node, "list_init must produce self-referential node");

// Output: node remains allocated and owned by the fuzzer runtime after this stub.
